 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the separator as a uniform interior row or column, favoring a
    # balanced split when incidental uniform lines also occur.
    candidates = []
    for c in range(w):
        if all(row[c] == grid[0][c] for row in grid):
            candidates.append((abs(c - (w - 1 - c)), 'v', c))
    for r in range(h):
        if all(x == grid[r][0] for x in grid[r]):
            candidates.append((abs(r - (h - 1 - r)), 'h', r))
    _, orient, k = min(candidates)
    if orient == 'v':
        left = [row[:k] for row in grid]
        right = [row[k+1:] for row in grid]
    else:
        left = grid[:k]
        right = grid[k+1:]
    H = min(len(left), len(right))
    W = min(len(left[0]), len(right[0]))
    lc = Counter(x for row in left for x in row)
    rc = Counter(x for row in right for x in row)
    common = set(lc) & set(rc)
    background = max(common, key=lambda x: lc[x] + rc[x])
    out = []
    for r in range(H):
        row = []
        for c in range(W):
            a, b = left[r][c], right[r][c]
            row.append(3 if a == b and a != background else background)
        out.append(row)
    return out

if __name__ == '__main__':
    pass
